<?php
namespace App\Domains\Comercial\LiveSales\Services;
use App\Domains\Comercial\LiveSales\Enums\EstadoInteraccionLiveEnum;use App\Domains\Comercial\LiveSales\Enums\EstadoSesionLiveEnum;use App\Models\InteraccionLive;use App\Models\Lead;use App\Models\Pedido;use App\Models\SesionLive;use RuntimeException;
class LiveSalesService {
public function validarSesionParaInteraccion(SesionLive $sesion):void{ if(in_array($sesion->estado_ses,[EstadoSesionLiveEnum::FINALIZADA,EstadoSesionLiveEnum::CANCELADA],true)) throw new RuntimeException('La sesión no admite interacciones.'); }
public function convertirEnLead(InteraccionLive $interaccion):Lead{ if($interaccion->cod_lead) throw new RuntimeException('La interacción ya fue convertida a lead.'); if($interaccion->cod_pedido) throw new RuntimeException('La interacción ya fue convertida a pedido.'); $lead=Lead::create(['nombre_lea'=>$interaccion->nombre_int ?: ($interaccion->alias_int ?: 'Interesado LIVE'),'alias_lea'=>$interaccion->alias_int,'telefono_lea'=>$interaccion->telefono_int,'producto_interes_lea'=>$interaccion->intencion_compra_int,'observacion_lea'=>$interaccion->observacion_int,'estado_lea'=>'nuevo','cod_canal_venta'=>$interaccion->sesionLive->cod_canal_venta,'cod_tipo_flujo_comercial'=>1,'cod_usuario_responsable'=>$interaccion->cod_usuario_responsable]); $interaccion->update(['cod_lead'=>$lead->cod_lead,'estado_int'=>EstadoInteraccionLiveEnum::CONVERTIDO_LEAD]); return $lead; }
public function convertirEnPedido(InteraccionLive $interaccion):Pedido{ if($interaccion->cod_pedido) throw new RuntimeException('La interacción ya fue convertida a pedido.'); $pedido=Pedido::create(['cod_cliente'=>null,'cod_canal_venta'=>$interaccion->sesionLive->cod_canal_venta,'cod_tipo_flujo_comercial'=>1,'cod_usuario_responsable'=>$interaccion->cod_usuario_responsable,'numero_pedido_ped'=>'LIVE-'.str_pad((string)(Pedido::max('cod_pedido')+1),6,'0',STR_PAD_LEFT),'fecha_pedido_ped'=>now()->toDateString(),'estado_ped'=>'borrador','subtotal_ped'=>0,'descuento_ped'=>0,'total_ped'=>0,'observacion_ped'=>'Pedido generado desde interacción live #'.$interaccion->cod_interaccion_live]); $interaccion->update(['cod_pedido'=>$pedido->cod_pedido,'estado_int'=>EstadoInteraccionLiveEnum::CONVERTIDO_PEDIDO]); return $pedido; }
}
